import { useHistory } from 'react-router-dom';
import { HOME_HREF } from '@salesforce/retail-react-app/app/constants';
import { useContentfulClient } from 'app/hooks/useContentfulClient';
import { filterByRegion, pickMostSpecificByRegion } from 'app/utils/resolveByRegion';
import type { FooterConfigEntry, FooterNavGroupEntry, LinkEntry } from 'app/types/contentful';
import { FooterNavColumn } from './footerNavColumn';
import { BottomBar } from './bottomBar';

const ZIMM_FOOTER_RECIPE = 'ZimmFooter';

// Contentful resolves nested references `include` levels deep, and the footer model is exactly
// three: footerConfig → navGroups (1) → links (2) → regions (3). Depth 3 is the minimum that
// populates `entry.fields.regions[].fields.siteId`, which filterByRegion reads — at 2 the region
// references come back unresolved and every link silently drops out of its scoped column. Not a
// house default: useContentful.ts uses 2 for flat content types that have no link fields.
const FOOTER_INCLUDE_DEPTH = 3;

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------
type FooterProps = {
  /** Contentful FooterConfigEntry. Pass FOOTER_FIXTURE from index.stories.content.ts in stories/tests. */
  data: FooterConfigEntry;
  copyrightYear?: number;
  /** Forces SubscribeSection into its post-submit state. For Storybook/tests only. */
  initialSubscribed?: boolean;
  /**
   * Opt in to the HPC-035 first/last-name capture modal. Defaults to false: SFCC-55 ships the
   * Stay in Touch section as an input plus submit button only, and the modal has no design yet.
   */
  enableNameCapture?: boolean;
  /** Click handler for the wordmark. Mirrors the header's onLogoClick prop, defaulting to
   *  noop so the presentational Footer never navigates on its own. */
  onLogoClick?: () => void;
  /** href for the Privacy Policy link inside the subscribe modal (HPC-037). Locale-aware at runtime. */
  privacyPolicyHref?: string;
};

// ---------------------------------------------------------------------------
// Footer
// ---------------------------------------------------------------------------

/**
 * Zimmermann global footer — presentational. Receives its content as props and fetches
 * nothing, matching every other Contentful-backed component in the repo (`DuplexSection`,
 * `HeroBanner`, `ProductHero`, `VideoEmbed`).
 *
 * Composed from independently-exported organisms/molecules (ui-kits/organisms/
 * zimmSubscribeSection, ui-kits/molecules/zimmContactIconRow via FooterNavColumn) rather than
 * defining them inline — see .claude/rules/overrideStyling.md for the reasoning. This file owns
 * only the footer's own shell layout: content row, nav-column wrapper, logo band, bottom bar.
 *
 * `data` is required by design: static content belongs in the story or in the container below,
 * never baked into the component that renders production UI. Omneo email submit and Cookie
 * Settings are separate stories (HPC-035, HPC-038).
 */
export const Footer = ({
  data,
  copyrightYear = new Date().getFullYear(),
  initialSubscribed = false,
  privacyPolicyHref = '#',
  onLogoClick = noop,
  enableNameCapture = false,
}: FooterProps) => {
  const {
    subscribeHeading,
    subscribeBody,
    navGroups,
    legalLinks = [],
    copyrightOwner,
    phoneHref,
    whatsAppHref,
    emailHref,
  } = data.fields;

  const legalItems = legalLinks.map((e) => ({ label: e.fields.label, href: e.fields.href }));
  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});

  return (
    <chakra.footer role="contentinfo" __css={styles.container}>
      <chakra.div __css={styles.main}>
        <chakra.div __css={styles.contentRow}>
          <chakra.div __css={styles.subscribe}>
            <ZimmSubscribeSection
              heading={subscribeHeading ?? ''}
              body={subscribeBody ?? ''}
              initialSubscribed={initialSubscribed}
              privacyPolicyHref={privacyPolicyHref}
              enableNameCapture={enableNameCapture}
            />
          </chakra.div>

          <chakra.div __css={styles.links}>
            <chakra.div __css={styles.linksInner}>
              {navGroups.map((group) => (
                <FooterNavColumn
                  key={group.sys.id}
                  group={group}
                  phoneHref={phoneHref}
                  whatsAppHref={whatsAppHref}
                  emailHref={emailHref}
                />
              ))}
            </chakra.div>
          </chakra.div>
        </chakra.div>

        <chakra.div __css={styles.logo}>
          {/* Button + programmatic nav, matching the header's wordmark rather than an <a href>.
              The handler comes from FooterContainer — see the note there on why it uses
              buildUrl + history.push rather than useNavigation. styles.logoButton is a chrome
              reset only, so the logo keeps its own geometry. */}
          <chakra.button type="button" aria-label="Zimmermann home" onClick={onLogoClick} __css={styles.logoButton}>
            <ZimmLogo variant="inverse" />
          </chakra.button>
        </chakra.div>
      </chakra.div>

      <BottomBar copyrightYear={copyrightYear} copyrightOwner={copyrightOwner ?? ''} legalLinks={legalItems} />
    </chakra.footer>
  );
};

// ---------------------------------------------------------------------------
// Container — the default export
// ---------------------------------------------------------------------------

/**
 * Contentful's `include`-resolved response nests navGroups/links/regions but applies no
 * region scoping of its own — narrow each region-aware array down to the current
 * storefront via the shared resolveByRegion utilities.
 */
export const scopeToRegion = (config: FooterConfigEntry, siteId: string): FooterConfigEntry => {
  const navGroups: FooterNavGroupEntry[] = config.fields.navGroups.map(
    (group): FooterNavGroupEntry => ({
      ...group,
      fields: { ...group.fields, links: filterByRegion<LinkEntry>(group.fields.links, siteId) },
    }),
  );
  const legalLinks: LinkEntry[] | undefined = config.fields.legalLinks
    ? filterByRegion<LinkEntry>(config.fields.legalLinks, siteId)
    : undefined;

  return { ...config, fields: { ...config.fields, navGroups, legalLinks } };
};

/**
 * The component SFCC actually renders. Base `_app/index.jsx` resolves
 * `@salesforce/retail-react-app/app/components/footer` through the overrides system and renders
 * `<Footer />` with **no props**, so there is no upstream container to own the data. This
 * wrapper is that seam, and the only place the Contentful fetch lives.
 *
 * HPC-034: fetches `footerConfig` entries via the Delivery API, then picks the entry scoped
 * to the current storefront's region (falls back to the global/unscoped entry once one
 * exists). Renders nothing while loading, on fetch failure, or when no entry resolves for
 * this region — no fallback to placeholder content once wired to live data, so a Contentful
 * outage doesn't silently ship stale placeholder copy to real shoppers. Note this puts a
 * fetch inside `components/`, which components.md reserves for containers; if that matters,
 * this should move into an `_app` override instead (Tier 2 shared shell — coordinate first).
 */
const FooterContainer = (props: Omit<FooterProps, 'data'>) => {
  // buildUrl + history.push, not useNavigation. useNavigation special-cases the home path
  // (`path === '/' ? '/' : updatedHref`), so navigate('/') pushes a bare '/' and skips the
  // site/locale prefix — on a prefixed storefront that drops the shopper onto the default
  // site. This is the exact pair base _app's onLogoClick uses, so both wordmarks resolve home
  // the same way on every storefront.
  //
  // useMultiSite ships untyped from the base SFCC package. site.id here is the resolved
  // SFCC site ID — confirmed against useCountryConfig.ts's identical client-side pattern
  // (`c.sfccSiteId === site?.id`), the existing precedent for this exact lookup.
  const { site, buildUrl } = useMultiSite() as {
    site: { id: string };
    buildUrl: (path: string, siteRef?: string, localeRef?: string) => string;
  };
  const history = useHistory();
  const { client } = useContentfulClient();
  const [footerData, setFooterData] = useState<FooterConfigEntry | null>(null);

  useEffect(() => {
    if (!client) return;
    let cancelled = false;

    client
      .getEntries({ content_type: 'footerConfig', include: FOOTER_INCLUDE_DEPTH })
      .then((response) => {
        if (cancelled) return;
        // The contentful SDK client is loosely typed (see useContentfulClient.ts) —
        // FooterConfigEntry mirrors the exact nested-resolved shape `include: 3` produces
        // for this content model.
        const configs = response.items as unknown as FooterConfigEntry[];
        const resolved = pickMostSpecificByRegion<FooterConfigEntry>(configs, site.id);
        setFooterData(resolved ? scopeToRegion(resolved, site.id) : null);
      })
      .catch(() => {
        if (!cancelled) setFooterData(null);
      });

    return () => {
      cancelled = true;
    };
  }, [client, site.id]);

  if (!footerData) return null;

  return <Footer data={footerData} onLogoClick={() => history.push(buildUrl(HOME_HREF))} {...props} />;
};

export default FooterContainer;

